mapper.select:
SELECT  FROM notification_email_template WHERE deleted = 0
AND id = #{templateId}
AND notification_code = #{notificationCode,typeHandler=com.sca4d.core.spring.persistence.mybatis.TreeCodeTypeHandler}
AND enabled = #{enabled}
ORDER BY notification_code, id

mapper.update:
UPDATE notification_email_template
notification_code = #{notificationCode.value,typeHandler=com.sca4d.core.spring.persistence.mybatis.TreeCodeTypeHandler}, locales = CAST(#{localesJson.value} AS JSONB), enabled = #{enabled.value}, version = version + 1
WHERE id = #{templateId} AND deleted = 0 AND version = #{expectedVersion}

UPDATE notification_email_template
SET deleted = 1, version = version + 1
WHERE id = #{templateId} AND enabled = FALSE AND deleted = 0 AND version = #{expectedVersion}
